param([int]$Runs=12,[string]$OutputDirectory=(Join-Path $PSScriptRoot 'reports'))
$ErrorActionPreference='Stop'
Set-Location -LiteralPath $PSScriptRoot
New-Item -ItemType Directory -Force -Path $OutputDirectory | Out-Null
function Percentile($Values,$P){$sorted=@($Values|Sort-Object); if(!$sorted.Count){return $null};$sorted[[math]::Max(0,[math]::Ceiling($sorted.Count*$P)-1)]}
function Run-Native([string]$Executable,[string[]]$Arguments){
 $info=[Diagnostics.ProcessStartInfo]::new();$info.FileName=(Join-Path $PSScriptRoot $Executable);$info.WorkingDirectory=$PSScriptRoot;$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true;$info.StandardOutputEncoding=[Text.Encoding]::UTF8;$info.StandardErrorEncoding=[Text.Encoding]::UTF8
 $quoted=@();foreach($argument in $Arguments){$escaped=[regex]::Replace($argument,'(\\*)"','$1$1\"');$escaped=[regex]::Replace($escaped,'(\\+)$','$1$1');$quoted+='"'+$escaped+'"'};$info.Arguments=$quoted -join ' ' 
 $process=[Diagnostics.Process]::new();$process.StartInfo=$info;$wall=[Diagnostics.Stopwatch]::StartNew();[void]$process.Start();$stdout=$process.StandardOutput.ReadToEndAsync();$stderr=$process.StandardError.ReadToEndAsync();$peak=0;while(!$process.HasExited){$process.Refresh();$peak=[math]::Max($peak,$process.WorkingSet64/1MB);if($wall.ElapsedMilliseconds -gt 60000){$process.Kill();throw "$Executable timed out"};Start-Sleep -Milliseconds 20};$wall.Stop();$result=[pscustomobject]@{ExitCode=$process.ExitCode;Stdout=$stdout.GetAwaiter().GetResult();Stderr=$stderr.GetAwaiter().GetResult();WallMs=$wall.Elapsed.TotalMilliseconds;CpuSeconds=$process.TotalProcessorTime.TotalSeconds;PeakWorkingSetMB=$peak};$process.Dispose();$result
}
$checks=@();foreach($exe in @('ajan-tests.exe','YerelAjanGateway.exe','YerelAjanSMS.exe')){$args=if($exe -eq 'YerelAjanGateway.exe'){@('--signature-test')}elseif($exe -eq 'YerelAjanSMS.exe'){@('--unicode-test')}else{@()};$run=Run-Native $exe $args;$checks+=[pscustomobject]@{name=$exe;passed=($run.ExitCode -eq 0);output=$run.Stdout.Trim();error=$run.Stderr.Trim()}}
$texts=@('Merhaba, size nasıl yardımcı olabilirim?','Randevunuz 15.10.2026 tarihinde saat 14:30 için onaylandı.','Toplam ücret 1.250,50 TL.','Ayşe Yılmaz, Çağrı Öztürk ve İpek Güneş.','Telefon numarası: +90 532 123 45 67.','Randevu kodu: B5D3056B.','Çalışma saatlerimiz 09:00–18:00.','Üç kişilik masa için rezervasyon oluşturabilirim.')
$tts=@();$allMetrics=@();for($i=0;$i -lt $texts.Count;$i++){$run=Run-Native 'YerelAjan.exe' @('--tts-bench',$texts[$i],(Join-Path $OutputDirectory "tts-$i.wav"),'--runs',([string]$Runs));if($run.ExitCode -eq 0){$data=$run.Stdout.Trim()|ConvertFrom-Json;$allMetrics+=@($data.metrics|Select-Object -Skip 1);$tts+=[pscustomobject]@{text=$texts[$i];passed=$true;model_load_ms=$data.model_load_ms;cold_to_first_pcm_ms=($data.model_load_ms+$data.metrics[0].first_pcm_ms);process_wall_ms=$run.WallMs;cpu_seconds=$run.CpuSeconds;process_peak_mb=$run.PeakWorkingSetMB;metrics=$data.metrics}}else{$tts+=[pscustomobject]@{text=$texts[$i];passed=$false;error=$run.Stderr.Trim()}}}
$values=@($allMetrics.first_pcm_ms);$summary=[ordered]@{timestamp=[DateTimeOffset]::Now.ToString('o');hardware=[ordered]@{cpu=(Get-CimInstance Win32_Processor).Name;physical_cores=(Get-CimInstance Win32_Processor).NumberOfCores;ram_gib=[math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory/1GB,2)};checks=$checks;tts=[ordered]@{successful_phrases=@($tts|Where-Object passed).Count;total_phrases=$texts.Count;first_pcm_p50_ms=(Percentile $values .50);first_pcm_p95_ms=(Percentile $values .95);first_pcm_p99_ms=(Percentile $values .99);first_pcm_max_ms=($values|Measure-Object -Maximum).Maximum;peak_process_mb=($tts.process_peak_mb|Measure-Object -Maximum).Maximum;target_first_pcm_p95_ms=250;target_passed=(@($tts|Where-Object {!$_.passed}).Count -eq 0 -and (Percentile $values .95) -le 250);details=$tts};live_channels=[ordered]@{physical_modem='not_verified';meta_whatsapp='not_verified';external_pbx='not_verified'};memory_4gb_8gb_os='not_verified; a process memory limit is not a total-RAM device test'}
$cancelCheck=Run-Native 'YerelAjan.exe' @('--speech-test');$summary.checks+=([pscustomobject]@{name='neural_cancellation';passed=($cancelCheck.ExitCode -eq 0);output=$cancelCheck.Stdout.Trim();error=$cancelCheck.Stderr.Trim()})
$english=@();$enWarm=@();foreach($phrase in @('Hello. How may I help you?','Your appointment is confirmed for tomorrow at ten.','The total is twelve pounds and fifty pence.')){
 $run=Run-Native 'YerelAjan.exe' @('--tts-en',$phrase,(Join-Path $OutputDirectory ('english-'+$english.Count+'.wav')),'--runs',([string]$Runs))
 if($run.ExitCode -eq 0){$data=$run.Stdout.Trim()|ConvertFrom-Json;$enWarm+=@($data.metrics|Select-Object -Skip 1);$english+=[pscustomobject]@{text=$phrase;passed=$true;model_load_ms=$data.model_load_ms;cold_to_first_pcm_ms=($data.model_load_ms+$data.metrics[0].first_pcm_ms);cpu_seconds=$run.CpuSeconds;wall_ms=$run.WallMs;peak_process_mb=$run.PeakWorkingSetMB;metrics=$data.metrics}}else{$english+=[pscustomobject]@{text=$phrase;passed=$false;error=$run.Stderr.Trim()}}
}
$summary['english_tts']=[ordered]@{successful_phrases=@($english|Where-Object passed).Count;total_phrases=3;first_pcm_p50_ms=(Percentile @($enWarm.first_pcm_ms) .50);first_pcm_p95_ms=(Percentile @($enWarm.first_pcm_ms) .95);first_pcm_p99_ms=(Percentile @($enWarm.first_pcm_ms) .99);first_pcm_max_ms=($enWarm.first_pcm_ms|Measure-Object -Maximum).Maximum;peak_process_mb=($english.peak_process_mb|Measure-Object -Maximum).Maximum;target_passed=(@($english|Where-Object {!$_.passed}).Count -eq 0 -and (Percentile @($enWarm.first_pcm_ms) .95) -le 250);details=$english}
foreach($report in @('agent-acceptance','sip-local','sip-baseline')){$path=Join-Path $OutputDirectory ($report+'.json');if(Test-Path -LiteralPath $path){$summary[$report]=Get-Content -LiteralPath $path -Raw -Encoding UTF8|ConvertFrom-Json}}
$summary['quality_review']='Synthetic pronunciation samples included; no human MOS or independently annotated speech WER validation.'
$summary|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $OutputDirectory 'benchmark.json') -Encoding utf8
$allMetrics|Select-Object first_pcm_ms,total_ms,audio_seconds,rtf,working_set_mb,peak_working_set_mb,private_mb,@{n='normalizer_ms';e={$_.stages.normalizer_ms}},@{n='text_ms';e={$_.stages.text_ms}},@{n='acoustic_ms';e={$_.stages.acoustic_ms}},@{n='decoder_ms';e={$_.stages.decoder_ms}}|Export-Csv -LiteralPath (Join-Path $OutputDirectory 'tts-metrics.csv') -NoTypeInformation -Encoding utf8
[pscustomobject]$summary.tts|Select-Object successful_phrases,total_phrases,first_pcm_p50_ms,first_pcm_p95_ms,first_pcm_p99_ms,first_pcm_max_ms,peak_process_mb,target_passed|Format-List
if(@($summary.checks|Where-Object {!$_.passed}).Count){exit 1}
if(!$summary.tts.target_passed -or !$summary.english_tts.target_passed){exit 2}
